<?php
require __DIR__.'/bootstrap.php';
use AranduGo\SiteRepository; use AranduGo\Support;
$d=SiteRepository::published(); $modules=array_values(array_filter($d['modules']??[],fn($m)=>!empty($m['active']))); $by=[]; foreach($modules as $m)$by[$m['key']]=$m;
