?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=Support::e($d['business']['name']??'Arandu Go')?></title><meta name="robots" content="<?=!empty($d['seo']['allowIndexing'])?'index,follow':'noindex,nofollow'?>"><link rel="stylesheet" href="<?=Support::url('assets/site.css')?>"><?php if(!empty($d['customCode']['css'])):?><style><?=$d['customCode']['css']?></style><?php endif;?></head><body id="inicio">
<header class="site-header" style="background:<?=Support::e($d['header']['background']??'#fff')?>;color:<?=Support::e($d['header']['text']??'#172033')?>"><a class="identity" href="#inicio"><?php if(($d['header']['identityType']??'initial')==='logo'&&!empty($d['header']['logo'])):?><img src="<?=Support::e($d['header']['logo'])?>" alt="Logo" style="height:<?=min(250,max(28,(int)$d['header']['logoSize']))?>px;<?=!empty($d['header']['maintainAspect'])?'width:auto':'width:'.(int)$d['header']['logoWidth'].'px'?>"><?php else:?><span class="identity-mark"><?=Support::e($d['header']['initial']??'A')?></span><?php endif;?><?php if(!empty($d['header']['showName'])):?><span><?=Support::e($d['header']['nameText']??$d['business']['name'])?></span><?php endif;?></a><button class="button alt menu-toggle" type="button" aria-label="Abrir menú">Menú</button><nav id="mainMenu"><?php foreach($d['menuOrder']??[] as $key):$setting=$d['menuSettings'][$key]??['visible'=>true];if($key!=='home'&&empty($setting['visible']))continue;?><a href="#<?=Support::e($anchors[$key]??$key)?>"><?=Support::e($menuLabels[$key]??$key)?></a><?php endforeach;?></nav><?php if($wa):?><a class="button" href="<?=$phoneHref($wa)?>">◉ WhatsApp</a><?php endif;?></header><main>
<?php foreach($modules as $m):$key=$m['key']; if($key==='hero'):?><section class="section hero" style="<?=$style('hero')?>"><div><p class="eyebrow"><?=Support::e($d['business']['category']??'')?></p><h1><?=Support::e($d['hero']['title']??'')?></h1><p><?=Support::e($d['hero']['text']??'')?></p><div class="cta-row"><?php if(!empty($d['hero']['showWhatsappCta'])&&$wa):?><a class="button" href="<?=$phoneHref($wa)?>">◉ WhatsApp</a><?php endif;?><?php if(!empty($d['hero']['showCallCta'])&&$call):?><a class="button alt" href="<?=$phoneHref($call)?>">☎ Llamar</a><?php endif;?><?php if(!empty($d['hero']['showMapsCta'])&&!empty($d['business']['mapsUrl'])):?><a class="button alt" href="#ubicacion">Cómo llegar</a><?php endif;?></div></div><?php if(!empty($d['hero']['showImage'])&&!empty($d['hero']['image'])):?><div class="hero-media"><img src="<?=Support::e($d['hero']['image'])?>" alt="<?=Support::e($d['business']['name'])?>"></div><?php endif;?></section>
<?php elseif($key==='quick'):?><section class="section" style="<?=$style('quick')?>"><div class="quick-grid" style="--cols:<?=max(1,min(4,(int)($d['quickLayout']['columns']??3)))?>"><?php foreach($d['quickOrder']??[] as $item):if($item==='address'&&!empty($d['quickVisible']['address'])):?><article class="card"><strong>⌖ Dirección</strong><p><?=Support::e($d['business']['address'])?></p></article><?php elseif($item==='hours'&&!empty($d['quickVisible']['hours'])):?><article class="card"><strong>◷ Horarios</strong><p><?=Support::e($d['business']['hours'])?></p></article><?php elseif($item==='email'&&!empty($d['quickVisible']['email'])):?><article class="card"><strong>✉ Correo</strong><p><?=Support::e($d['business']['email'])?></p></article><?php elseif(str_starts_with($item,'phone:')):$id=substr($item,6);foreach($phones as $p)if($p['id']===$id&&!empty($p['showInQuick'])&&!empty($p['number'])):?><a class="card" href="<?=$phoneHref($p)?>"><strong><?=($p['type']==='whatsapp'?'◉':($p['type']==='mobile'?'▣':'☎'))?> <?=Support::e($p['label'])?></strong><p><?=Support::e($p['number'])?></p></a><?php endif;endforeach;endif;endforeach;?></div></section>
<?php elseif($key==='about'):?><section id="nosotros" class="section" style="<?=$style('about')?>"><p class="eyebrow">Sobre el negocio</p><h2><?=Support::e($d['about']['title']??'')?></h2><p><?=nl2br(Support::e($d['about']['text']??''))?></p></section>
<?php elseif($key==='services'):?><section id="servicios" class="section" style="<?=$style('services')?>"><p class="eyebrow">Servicios / Productos</p><h2>Lo que ofrecemos</h2><div class="service-grid"><?php foreach($d['services']??[] as $s):?><article class="card"><h3><?=Support::e($s['title'])?></h3><p><?=Support::e($s['description'])?></p></article><?php endforeach;?></div></section>
<?php elseif($key==='gallery'):?><section id="galeria" class="section" style="<?=$style('gallery')?>"><p class="eyebrow">Galería</p><h2>Imágenes del negocio</h2><div class="gallery-grid" style="--cols:<?=max(1,min(4,(int)($d['galleryLayout']['columns']??3)))?>"><?php foreach(array_filter($d['gallery']??[],fn($g)=>!empty($g['visible'])) as $g):?><article class="card gallery-card"><img src="<?=Support::e($g['image'])?>" alt="<?=Support::e($g['title'])?>"><div><h3><?=Support::e($g['title'])?></h3><p><?=Support::e($g['description'])?></p><?php if(!empty($g['ctaLabel'])&&!empty($g['ctaUrl'])):?><a class="button" href="<?=Support::e($g['ctaUrl'])?>"><?=Support::e($g['ctaLabel'])?></a><?php endif;?></div></article><?php endforeach;?></div></section>
