<?php elseif($key==='contact'):?><section id="contacto" class="section contact-grid" style="<?=$style('contact')?>"><div><p class="eyebrow">Contacto</p><h2>¿Tenés alguna consulta?</h2><?php foreach(array_filter($phones,fn($p)=>!empty($p['showInContact'])&&!empty($p['number'])) as $p):?><p><a href="<?=$phoneHref($p)?>"><strong><?=Support::e($p['label'])?>:</strong> <?=Support::e($p['number'])?></a></p><?php endforeach;?><p><a href="mailto:<?=Support::e($d['business']['email']??'')?>"><?=Support::e($d['business']['email']??'')?></a></p></div><?php if(!empty($d['contactForm']['enabled'])):?><form class="contact-form" method="post" action="<?=Support::url('contact.php')?>"><input name="name" placeholder="Nombre" required><input type="email" name="email" placeholder="Correo" required><input name="phone" placeholder="Teléfono"><textarea name="message" placeholder="Mensaje" required></textarea><input name="website" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px"><?php if(($d['contactForm']['captchaType']??'none')==='integrated'):?><label><input type="checkbox" name="human" value="1" required> Soy una persona</label><?php endif;?><button class="button">Enviar consulta</button></form><?php endif;?></section>
<?php elseif($key==='social'):?><section class="section" style="<?=$style('social')?>"><p class="eyebrow">Redes sociales</p><h2>Seguinos</h2><div class="social-row"><?php foreach($d['socials']??[] as $network=>$url)if($url):?><a href="<?=Support::e($url)?>" target="_blank" rel="noopener"><?=Support::e(ucfirst($network))?></a><?php endforeach;?></div></section>
<?php elseif(in_array($key,['free1','free2'],true)):$free=current(array_filter($d['freeSections']??[],fn($f)=>$f['id']===$key));if($free):?><section id="<?=$key?>" class="section" style="<?=$style($key)?>"><p class="eyebrow"><?=Support::e($free['publicLabel']??'Información')?></p><h2><?=Support::e($free['title'])?></h2><div><?=$free['html']?></div><?php foreach($free['media']??[] as $media):?><?php if($media['type']==='image'):?><img src="<?=Support::e($media['url'])?>" alt="<?=Support::e($media['caption'])?>"><?php endif;?><?php endforeach;?><?php if(!empty($free['ctaLabel'])&&!empty($free['ctaUrl'])):?><a class="button" href="<?=Support::e($free['ctaUrl'])?>"><?=Support::e($free['ctaLabel'])?></a><?php endif;?></section><?php endif;endif;endforeach;?></main>
<footer class="site-footer" style="background:<?=Support::e($d['footer']['background']??'#fff')?>;color:<?=Support::e($d['footer']['text']??'#526078')?>"><p><?=Support::e($d['footer']['legalText']??'')?></p><?php if(!empty($d['footer']['showLegalLinks'])):?><a href="<?=Support::url('terminos.php')?>">Términos</a><a href="<?=Support::url('privacidad.php')?>">Privacidad</a><?php endif;?></footer><div class="mobile-actions"><?php if($wa):?><a href="<?=$phoneHref($wa)?>">◉ WhatsApp</a><?php endif;?><?php if($call):?><a href="<?=$phoneHref($call)?>">☎ Llamar</a><?php endif;?><a href="#ubicacion">⌖ Cómo llegar</a></div><script>document.querySelector('.menu-toggle')?.addEventListener('click',()=>document.querySelector('#mainMenu').classList.toggle('open'));</script><?=$d['customCode']['analytics']??''?></body></html>
